head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17301";
scwin.upd_attachBinFiles = null;
scwin.upd_attachBinFiles2 = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — qnaList, param.modifyYn, uploadCode, loadTp

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachBinFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles"]');
        scwin.upd_attachBinFiles2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles2"]');
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil17301.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_chrgNm", fn: function(){ return (!(String(((dma_corpDisclsChrg1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg1.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg1.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_2", fn: function(){ return (!(String(((dma_corpDisclsChrg2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg2.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg2.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_3", fn: function(){ return (!(String(((dma_corpDisclsChrg3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg3.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg3.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_4", fn: function(){ return (!(String(((dma_corpDisclsChrg4.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg4.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg4.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg4.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_4", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "if_attachFileNm", fn: function(){ return (!(String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_2", fn: function(){ return ((String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_3", fn: function(){ return (!(String(((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_qnaList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_20", fn: function(){ return (!(String(((dma_pageContext.get("qnaList") ?? "")) == null ? '' : ((dma_pageContext.get("qnaList") ?? ""))).length === 0)); } }, { id: "if_chrgNm_5", fn: function(){ return (!(String(((dma_corpDisclsChrg1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg1.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg1.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_6", fn: function(){ return (!(String(((dma_corpDisclsChrg2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg2.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg2.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_7", fn: function(){ return (!(String(((dma_corpDisclsChrg3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg3.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg3.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_8", fn: function(){ return (!(String(((dma_corpDisclsChrg4.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg4.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg4.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg4.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_8", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "c_when_108", fn: function(){ return ((String(((dma_pageContext.get("qnaList") ?? "")) == null ? '' : ((dma_pageContext.get("qnaList") ?? ""))).length === 0) && (String(((dma_pageContext.get("modifyYn") ?? "")) == null ? '' : ((dma_pageContext.get("modifyYn") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb4", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
        const loadTp = (String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))));
        if (loadTp === '2') {
            await scwin.checkSave();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17301.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_inDataYn_onclick
 * @description rd_inDataYn 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_inDataYn_onclick = function(e){
    try {
        scwin.inCharge('N')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17301.rd_inDataYn_onclick' }); }
};

/**
 * @method
 * @name slc_name1_onchange
 * @description 「등록자명」 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_name1_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.selCharge(selfVar.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17301.slc_name1_onchange' }); }
};

/**
