        await scwin.checkByte($c.util.getComponent("txa_quesContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17301.txa_quesContn_onkeyup' }); }
};

/**
 * @method
 * @name txa_quesContn_onchange
 * @description 「${ entity.quesContn }」 변경 이벤트
