/**
 * @method
 * @name btn_FileDown_onclick
 * @description 「현재 등록된 파일 : ${ entity.attachFileNm }」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDown_onclick = function(e){
    try {
        fn_FileDown('' + dlt_qnaList.getCellData(0, "contnId") + '','' + dlt_qnaList.getCellData(0, "contnAttachSeq") + '','' + dlt_qnaList.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17301.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_deleteAttachFile_onclick
 * @description btn_deleteAttachFile 클릭 이벤트
 * @param {Object} e 이벤트 객체
