 */
scwin.btn_deleteAttachFile_onclick = function(e){
    try {
        scwin.deleteAttachFile('' + dlt_qnaList.getCellData(0, "contnId") + '','' + dlt_qnaList.getCellData(0, "contnAttachSeq") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17301.btn_deleteAttachFile_onclick' }); }
};

/**
 * @method
 * @name btn_register_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
