/**
 * @method
 * @name rd_inDataYn2_onclick
 * @description rd_inDataYn2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_inDataYn2_onclick = function(e){
    try {
        scwin.inCharge('N')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17301.rd_inDataYn2_onclick' }); }
