scwin.slc_name12_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.selCharge(selfVar.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17301.slc_name12_onchange' }); }
};

/**
 * @method
 * @name txa_quesContn2_onkeyup
 * @description 「질의내용」 키 입력 이벤트
