    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17301.btn_register_2_onclick' }); }
};

/**
 * @method
 * @name btn_goList_2_onclick
 * @description 「목록」 클릭 이벤트
