        await scwin.goList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17301.btn_goList_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goList
 * @description go List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goList = async function () {
    const sbmOptions = {
        id: "tx_fn_goList",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_goListReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_registerReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
    if (uploadCode === '0') {
        await $c.win.alert('저장되었습니다.');
    } else {
        if (uploadCode === '1') {
            await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
        } else {
            if (uploadCode === '2') {
                await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
            } else {
                await $c.win.alert('저장시 오류가 발생하였습니다.');
            }
        }
    }
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    const frm = (document.QnaInfoForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchQnaList');
    const nr = await scwin.tx_fn_goList();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17300/jldfil17300.xml", { "method": 'searchQnaList' });
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    let q_name = "";
    if (document.getElementsByName("rd_inDataYn")[0].checked === true) {
        q_name = document.getElementsByName("slc_name1");
        let q_cnt = 0;
        for (let n = 0; n < q_name.length; n++) {
            if (q_name[n].value === "0" || q_name[n].value === "1" || q_name[n].value === "2") {
                q_cnt++;
                q_name[n].checked === true;
            }
        }
        if (q_cnt === 0) {
            $c.util.getComponent('ipt_questrTelNo').setValue("");
            $c.util.getComponent('ipt_questrEmail').setValue("");
            await $c.win.alert("'등록자명' 항목을 선택하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
    } else {
        if (document.getElementsByName("rd_inDataYn")[1].checked === true) {
            q_name = $c.util.getComponent("ipt_name2");
            if (await scwin.nullChk(q_name)) {
                return;
            }
        } else {
            await $c.win.alert("'등록자정보'를 선택하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_questrTelNo"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_questrEmail"))) {
        return;
    }
    if (await scwin.isNull($c.util.getComponent("slc_quesBzTpCd"), '업무구분')) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_quesTitle"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("txa_quesContn"))) {
        return;
    }
    const frm = (document.QnaInfoForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goListReq').set('method', 'registQna');
    $c.util.getComponent('dma_goListReq').set('modifyYn', '' + dma_pageContext.get("modifyYn") + '');
    $c.util.getComponent('dma_goListReq').set('contnId', '' + dma_pageContext.get("contnId") + '');
    $c.util.getComponent('dma_goListReq').set('contnAttachSeq', '' + dma_pageContext.get("contnAttachSeq") + '');
    if (document.getElementsByName("rd_inDataYn")[1].checked === true) {
        $c.util.getComponent('dma_goListReq').set('questrNm', q_name.value);
    }
    await scwin.tx_fn_register();
};

